export const roadmaps: Roadmap[] = baseRoadmaps.map((roadmap) => {
  const additions = extensionTitles[roadmap.careerId] ?? []
  const stages = [...roadmap.stages]
  for (const title of additions) {
    const previous = stages[stages.length - 1]
    stages.push({
      id: stageId(roadmap.careerId, title),
      roadmapId: roadmap.id,
      careerId: roadmap.careerId,
      order: stages.length + 1,
      title,
      description: `Extend your ${roadmap.title.replace(' Roadmap', '')} skills through guided practice, a portfolio project, and workplace preparation.`,
      difficulty: stages.length < 6 ? 'intermediate' : 'advanced',
      prerequisiteStageId: previous.id,
      learningObjectives: [`Apply ${title.replace(' & Job Readiness', '')} concepts in a guided project`, 'Document decisions, evidence, and quality checks clearly', 'Prepare a practical portfolio artifact for review'],
    })
  }
  return { ...roadmap, stages }
})

export function getRoadmapByCareerId(careerId?: string) {
  if (!careerId) return undefined
  if (careerId === 'data-analytics-artificial-intelligence') {
    return roadmaps.find((roadmap) => roadmap.careerId === 'data-analytics')
  }
  return roadmaps.find((roadmap) => roadmap.careerId === careerId)
}

export function getStageById(careerId?: string, stageId?: string) {
  return getRoadmapByCareerId(careerId)?.stages.find((stage) => stage.id === stageId)
}

export function getStageStatus(stage: RoadmapStage): 'available' | 'locked' {
  return stage.prerequisiteStageId ? 'locked' : 'available'
}
